```javascript
const axios = require("axios");

async function getData(input) {
  const data = {
    url: input
  };

  const config = {
    headers: {
      'Content-Type': 'application/json'
    }
  };

  try {
    const response = await axios.post("https://api.viesnap.com/info", data, config);
    return response.data;
  } catch (error) {
    return {
      error: error.message
    };
  }
}

